fn solve(n: i8) -> i8 {
    // We extract as many 100-unit notes as possible,
    // then as many 20s, 10s, 5s, and finally 1s.
    let mut amount = n;
    let mut count: i8 = 0;

    // 100-unit notes
    let c100 = amount / 100;
    count += c100;
    amount %= 100;

    // 20-unit notes
    let c20 = amount / 20;
    count += c20;
    amount %= 20;

    // 10-unit notes
    let c10 = amount / 10;
    count += c10;
    amount %= 10;

    // 5-unit coins
    let c5 = amount / 5;
    count += c5;
    amount %= 5;

    // 1-unit coins (what's left)
    count + amount
}